mapper.select:
SELECT r.id, r.request_id, r.member_id, r.schedule_id, r.start_time, r.end_time, r.persons,
       r.member_card_id, r.status, r.reservation_time, r.cancel_time, r.cancel_reason, r.check_in_time,
       r.create_by, r.create_time, r.update_by, r.update_time
FROM t_reservation r
LEFT JOIN t_schedule s ON s.id = r.schedule_id
LEFT JOIN t_member_card c ON c.id = r.member_card_id


        AND s.store_id = #{query.storeId}


        AND s.course_id = #{query.courseId}


        AND c.card_type = #{query.cardType}


        AND r.schedule_id = #{query.scheduleId}


        AND r.member_id = #{query.memberId}


        AND r.status = #{query.status}


        AND r.start_time >= #{startTime}


        AND r.start_time < #{endTimeExclusive}


ORDER BY r.reservation_time DESC, r.id DESC
